input.script:
users = list_users({})
dates = ["2026-06-15", "2026-06-16", "2026-06-17", "2026-06-18", "2026-06-19"]
times = ["09:00", "09:30", "10:00", "10:30", "11:00", "11:30", "12:00", "12:30", "13:00", "13:30", "14:00", "14:30", "15:00", "15:30", "16:00"]
endtimes = ["10:00", "10:30", "11:00", "11:30", "12:00", "12:30", "13:00", "13:30", "14:00", "14:30", "15:00", "15:30", "16:00", "16:30", "17:00"]

days = for date in dates {
  busy_per_user = for user in users {
    a = get_availability({ user_id: user.id, date: date })
    return a.busy
  }
  return { date: date, busy_per_user: busy_per_user }
}

found = fold acc = null for day in days {
  day_found = fold sacc = null for i in list.range(0, 15) {
    smin = 540 + i * 30
    emin = smin + 60
    all_free = fold f = true for busy in day.busy_per_user {
      ov = fold o = false for iv in busy {
        ps = text.split(iv.start, ":")
        pe = text.split(iv.end, ":")
        bs = number.parse(ps[0]) * 60 + number.parse(ps[1])
        be = number.parse(pe[0]) * 60 + number.parse(pe[1])
        return o or (bs < emin and be > smin)
      }
      return f and not ov
    }
    return sacc if sacc != null else (i if all_free else null)
  }
  return acc if acc != null else ({ date: day.date, idx: day_found } if day_found != null else null)
}

r = found if found != null else fail("NO_SLOT", "no suitable slot found in the week")
answer = { start: r.date + "T" + times[r.idx] + ":00Z", end: r.date + "T" + endtimes[r.idx] + ":00Z" }
res = submit_result({ answer: answer })
return { answer: answer, submitted: res }

